 static void Tick(){string q="docs/verification/v10/verify-request.txt";if(EditorApplication.isCompiling||!EditorApplication.isPlaying||!File.Exists(q))return;var cmd=File.ReadAllText(q).Trim();if(cmd.Length==0)return;File.WriteAllText(q,"");var t=UnityEngine.Object.FindObjectOfType<MerchantTrade>();if(cmd=="suite"){var p=t.GetComponent<EnemyProbe>();if(p==null)p=t.gameObject.AddComponent<EnemyProbe>();p.Run();}}
}
