 foreach(bool aim in new[]{false,true}){view.TestADS=aim;foreach(float angle in new[]{70f,85f}){Set("desiredPitch",-angle);yield return new WaitForSeconds(.65f);yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(D+"up"+angle+(aim?"-ads":"-shoulder")+".png");Check(motor.GetComponent<UpwardPlayerVisibility>().Visibility<.001f,"high-up self occluder hidden at "+angle+" ADS="+aim);if(aim)Check(view.AimViewport.x>0&&view.AimViewport.x<1&&view.AimViewport.y>0&&view.AimViewport.y<1,"high-up fallback aim on screen "+angle);}view.TestLook=new Vector2(0,80);yield return new WaitForEndOfFrame();view.TestLook=Vector2.zero;yield return new WaitForSeconds(.8f);Check(Mathf.Abs(Get("desiredPitch")+90)<.001f,"upward clamp reaches exactly90 "+aim);Quaternion prev=view.transform.rotation;Vector3 previousPosition=view.transform.position;for(int i=0;i<35;i++){yield return new WaitForEndOfFrame();maxPoleDisplacement=Mathf.Max(maxPoleDisplacement,Vector3.Distance(previousPosition,view.transform.position));previousPosition=view.transform.position;minUp=Mathf.Min(minUp,Vector3.Dot(view.transform.forward,Vector3.up));maxPoleJitter=Mathf.Max(maxPoleJitter,Quaternion.Angle(prev,view.transform.rotation));prev=view.transform.rotation;CheckFinite();}CaptureNow(D+(aim?"vertical-ads":"vertical-shoulder")+".png");s.ResetSimulation();yield return new WaitForSeconds(.9f);Check(s.Magazine.Ready&&s.ReadyVisual.gameObject.activeSelf&&s.ReadyVisual.GetComponent<Renderer>().forceRenderingOff,"ready loading retained while upward visual hidden "+aim);int upBefore=OrbProjectile.SpawnCount;recordingUp=true;s.TestFire=true;float shotUntil=Time.time+1.2f;while(OrbProjectile.SpawnCount==upBefore&&Time.time<shotUntil)yield return new WaitForEndOfFrame();s.TestFire=false;recordingUp=false;var flights=FindObjectsOfType<OrbProjectile>();bool visibleFlight=flights.Any(p=>p.GetComponent<Renderer>()!=null&&!p.GetComponent<Renderer>().forceRenderingOff);upwardShots.Add(new UpShot{ads=aim,spawnDelta=OrbP