 void CheckFinite(){Vector3 p=view.transform.position;if(float.IsNaN(p.x)||float.IsNaN(p.y)||float.IsNaN(p.z)||float.IsInfinity(p.x)||float.IsInfinity(p.y)||float.IsInfinity(p.z))throw new Exception("Nonfinite camera");}
